const args = $input.first().json;
const filters = ["{Estado} = 'Disponible'", '{Stock} > 0'];
if (args.tipo && ['BN','COLOR'].includes(String(args.tipo).toUpperCase())) {
  filters.push(`{Tipo} = "${String(args.tipo).toUpperCase()}"`);
}
if (args.modelo_query) {
  filters.push(`FIND(LOWER("${String(args.modelo_query).toLowerCase()}"), LOWER({Modelo})) > 0`);
}
return [{ json: { ...args, _formula: `AND(${filters.join(', ')})` } }];

const matches = $input.all().map(i => i.json);

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: 'No hay equipos refurbished disponibles con esos criterios. Sugerí derivar al comercial para que confirme próximas reposiciones.',
    trace_id: $execution.id
  } }];
}

const equipos = matches.map(r => ({
  modelo: r.Modelo,
  tipo: r.Tipo || '',
  copias_total: r['Copias Total'] || 0,
  stock: r.Stock || 0,
  ubicacion: r['Ubicación'] || 'PEPIRI',
  accesorios: r['Accesorios'] || ''
}));

const totalUnidades = equipos.reduce((s, e) => s + (e.stock || 0), 0);

return [{ json: {
  status: 'RESOLVED',
  data: {
    equipos_disponibles: equipos.slice(0, 10),
    total_modelos: equipos.length,
    total_unidades: totalUnidades
  },
  message_to_agent: `Hay ${equipos.length} modelos refurbished disponibles en PEPIRI (${totalUnidades} unidades totales). Ofrecele al cliente coordinar visita al showroom o cotización por modelo específico. El comercial cotiza caso por caso.`,
  trace_id: $execution.id
} }];
